# Phần "Lưu ý" ngắn hiển thị dưới lời giải: quy tắc cốt lõi hoặc chỗ hay nhầm của từng dạng bài.
# Khóa là tên hàm sinh câu (các vị trí 32–34 dùng hàm không tên nên lấy khóa là vị trí 'c32', 'c33', 'c34').
# Dạng nào chưa có ghi chú thì web chỉ hiện lời giải. Câu lí thuyết đã giải thích từng phương án nên không cần ghi chú.
NOTES = {
    # ----- véc tơ, độc lập tuyến tính, hạng -----
    's1': r'Viết đẳng thức véc tơ theo từng tọa độ để được hệ phương trình tuyến tính; với phương trình véc tơ, chuyển vế như phương trình số.',
    'h1': r'$u \perp v \Leftrightarrow \langle u, v\rangle = 0$; khi đó $|u + v|^2 = |u|^2 + |v|^2$.',
    'n1a': r'$\cos\alpha = \dfrac{\langle u, v\rangle}{|u|\,|v|}$; dấu của $\cos\alpha$ là dấu của tích vô hướng.',
    'n1c': r'Khai triển như hằng đẳng thức với $\langle u, u\rangle = |u|^2$; đừng quên số hạng chéo $2pq\langle u, v\rangle$.',
    'n1b': r'Hệ số chiếu $t = \dfrac{\langle u, v\rangle}{\langle v, v\rangle}$: chia cho $|v|^2$, không phải $|v|$.',
    'n1d': r'Góc nhọn $\Leftrightarrow \langle u, v\rangle > 0$, góc tù $\Leftrightarrow \langle u, v\rangle < 0$; các giá trị làm tích vô hướng bằng 0 (góc vuông) bị loại.',
    's2': r'Một véc tơ khác không luôn độc lập tuyến tính; hai véc tơ độc lập khi không cùng phương; trong $\mathbb{R}^n$ không có hệ độc lập nào nhiều hơn $n$ véc tơ.',
    'n2b': r'Tọa độ đối với cơ sở $B$ là nghiệm của hệ $xb_1 + yb_2 = v$, không phải tọa độ thông thường của $v$.',
    'n2e': r'Chuyển $u_3$ sang vế phải thì đổi dấu: $xu_1 + yu_2 = -u_3$.',
    'n2a': r'Ba véc tơ trong $\mathbb{R}^3$ là cơ sở $\Leftrightarrow$ định thức của chúng khác 0; véc tơ là tổ hợp tuyến tính của $u_1, u_2$ thì bị loại.',
    'n2d': r'Số véc tơ đã bằng số chiều nên chỉ cần định thức khác 0.',
    's3': r'Hạng = số hàng khác không của dạng bậc thang; số véc tơ thừa = số véc tơ $-$ hạng.',
    'h3': r'Số chiều không gian nghiệm của $AX = 0$ bằng số ẩn trừ hạng của $A$.',
    'n3a': r'Chỉ dùng biến đổi sơ cấp trên hàng; hạng không vượt quá số hàng và số cột.',
    'n3b': r'Hệ sinh ra $\mathbb{R}^4$ khi hạng bằng 4, nên cần thêm ít nhất $4 -$ hạng véc tơ.',
    'n3d': r'$\operatorname{rank}(AB) \le \min\{\operatorname{rank}A, \operatorname{rank}B\}$, nên tích của ma trận $3\times2$ với $2\times3$ không thể có hạng 3.',
    's23': r'Đưa về dạng bậc thang; hạng giảm đúng khi hàng cuối thành hàng không, điều kiện đó cho giá trị của $m$.',
    'n23b': r'$v$ thuộc không gian sinh bởi $u_1, u_2$ khi ba véc tơ phụ thuộc tuyến tính, tức định thức bằng 0.',
    'n23a': r'$\det A = 0$ mới cho biết hạng nhỏ hơn 3; phải thay từng giá trị $m$ để biết hạng bằng 1 hay 2.',
    # ----- ma trận, định thức, nghịch đảo -----
    's4': r'Phép nhân ma trận không giao hoán: $(A + B)(A - B) = A^2 - AB + BA - B^2$; luôn giữ đúng thứ tự các thừa số.',
    'h4': r'Dùng hệ thức $A^2 = pA + qI$ để hạ bậc dần ($A^3 = A\cdot A^2$), không cần nhân ma trận nhiều lần.',
    'n4a': r'Tính $A^2, A^3$ để thấy quy luật; với $A = cI + N$, $N^2 = 0$ thì $A^n = c^nI + nc^{n-1}N$.',
    'n4c': r'$(AB)^T = B^TA^T$ (đảo thứ tự) nên hai số hạng đầu triệt tiêu.',
    'n4b': r'Với ma trận cấp 2: $A^2 = (\operatorname{tr}A)A - (\det A)I$, nên $x$ là vết và $y = -\det A$.',
    'n4d': r'Khi $A^2 = A$ thì mọi lũy thừa của $A$ đều bằng $A$; và $C_n^1 + \dots + C_n^n = 2^n - 1$.',
    's5': r'$A$ khả nghịch $\Leftrightarrow \det A \ne 0$: đếm các số nguyên trong đoạn rồi trừ các nghiệm của $\det A = 0$ nằm trong đoạn.',
    'h5': r'Phần tử hàng $i$, cột $j$ của $A^{-1}$ là $\dfrac{A_{ji}}{\det A}$: chỉ số bị đảo, và nhớ dấu $(-1)^{i+j}$.',
    'n5b': r'Không khả nghịch $\Leftrightarrow \det A = 0$; tổng và tích các nghiệm có thể lấy từ định lí Viète.',
    'n5d': r'$\det\left(A^{-1}\right) = \dfrac{1}{\det A}$ và $\det(kA) = k^n\det A$ với $n$ là cấp của ma trận.',
    'n5a': r'Lỗi hay gặp: quên lũy thừa $k^3$ khi đưa hằng số ra ngoài định thức cấp 3.',
    'n5c': r'Chỉ áp dụng khi một khối ngoài đường chéo toàn số 0; khối còn lại không ảnh hưởng tới định thức.',
    's7': r'$\det(kA) = k^n\det A$, $\det\left(A^{-1}\right) = \dfrac{1}{\det A}$, $\det\left(A^T\right) = \det A$, $\det(AB) = \det A\cdot\det B$.',
    'h7': r'Cộng bội của một hàng vào hàng khác không làm đổi định thức; đưa về dạng tam giác (hoặc tam giác khối) rồi nhân các phần tử (khối) trên đường chéo.',
    's24': r'$AX = B \Rightarrow X = A^{-1}B$ (nhân bên trái); $XA = B \Rightarrow X = BA^{-1}$ (nhân bên phải); không được đổi thứ tự.',
    'n24e': r'Giải như phương trình số nhưng phải chuyển vị $B$ trước; chia ma trận cho một số là chia từng phần tử.',
    'n24a': r'Không cần tìm $X$: lấy định thức hai vế, $\det(AX) = \det A\cdot\det X$.',
    'n24c': r'$A^2X = B \Rightarrow X = A^{-1}A^{-1}B$: nhân $A^{-1}$ vào bên trái hai lần.',
    'n24d': r'Đặt $X$ với bốn ẩn, tính $AX$ và $XA$ rồi so sánh từng phần tử.',
    's46': r'Viết ma trận ra từ công thức của $a_{ij}$, rồi dùng $\det\left(A^T\right) = \det A$ và $\det(AB) = \det A\cdot\det B$.',
    'h46': r'Viết ma trận ra từ công thức của $a_{ij}$, khử về dạng tam giác; $\det\left(A^T\right) = \det A$, $\det(AB) = \det A\cdot\det B$.',
    'n46c': r'Định thức Vandermonde bằng tích các hiệu (số đứng sau trừ số đứng trước).',
    'n46b': r'$\det\left(A^{-1}B\right) = \dfrac{\det B}{\det A}$: không cần tìm ma trận nghịch đảo.',
    'n46a': r'Lập $\det A$ theo $m$ rồi giải phương trình; chỉ nhận nghiệm nguyên dương.',
    'n46d': r'$A + A^T$ đối xứng; $A - A^T$ phản đối xứng, và ma trận phản đối xứng cấp lẻ luôn có định thức bằng 0.',
    # ----- hệ phương trình tuyến tính, ứng dụng -----
    's22': r'Kiểm tra cỡ ma trận trước khi nhân (số cột của ma trận trước bằng số hàng của ma trận sau); với mô hình Leontief giải $(I - A)X = D$.',
    'h22': r'Ở trạng thái ổn định, lượng khách rời X mỗi tháng bằng lượng khách chuyển đến X; kết quả không phụ thuộc số khách ban đầu.',
    's25': r'Xét hàng cuối sau khi khử: hệ số bằng 0 mà vế phải khác 0 thì vô nghiệm; cả hai bằng 0 thì vô số nghiệm; hệ số khác 0 thì nghiệm duy nhất.',
    'h25': r'Hệ hai phương trình hai ẩn có vô số nghiệm khi các hệ số và vế phải tỉ lệ: $\dfrac{a_1}{a_2} = \dfrac{b_1}{b_2} = \dfrac{c_1}{c_2}$.',
    'n25c': r'Số phương trình nhiều hơn số ẩn: giải hai phương trình rồi buộc phương trình còn lại nghiệm đúng.',
    'n25a': r'Hệ thuần nhất vuông có nghiệm khác không $\Leftrightarrow \det A = 0$.',
    'n25b': r'Số chiều không gian nghiệm = số ẩn $-$ hạng của ma trận hệ số.',
    's29': r'Lập hệ phương trình từ điều kiện của bài toán (cung bằng cầu, hoặc dùng hết nguyên liệu) rồi giải bằng phép khử Gauss.',
    'g1': r'Tổng các trị riêng bằng vết, tích các trị riêng bằng định thức của ma trận.',
    'hg1': r'Nếu $A = PDP^{-1}$ thì $A^n = PD^nP^{-1}$: vết của $A^n$ bằng tổng lũy thừa bậc $n$ của các trị riêng.',
    'ngL1': r'Hệ vuông có nghiệm duy nhất $\Leftrightarrow \det A \ne 0$.',
    'ngL2': r'Định thức khác 0 thì ba véc tơ là một cơ sở, nên biểu diễn của $v$ qua chúng là duy nhất.',
    'ngL3': r'Tính $f(A)$: thay $x$ bằng $A$ và hằng số $c$ bằng $cI$.',
    # ----- giới hạn, liên tục, khả vi -----
    's8': r'Thay vô cùng bé tương đương chỉ dùng được trong tích và thương; với hiệu hai vô cùng bé cùng bậc phải khai triển Maclaurin đến bậc cao hơn.',
    'h8': r'Khai triển tử và mẫu đến bậc đầu tiên khác 0; dừng sớm sẽ lại gặp dạng $\dfrac00$.',
    's9': r'Liên tục tại $x_0$ $\Leftrightarrow$ giới hạn trái = giới hạn phải = $f(x_0)$; giới hạn hữu hạn mà mẫu tiến về 0 thì tử cũng phải tiến về 0.',
    'h9': r'Tiệm cận đứng: nghiệm của mẫu không bị rút gọn với tử; tiệm cận ngang: xét riêng $x \to +\infty$ và $x \to -\infty$ (với căn thức, hai phía có thể khác nhau).',
    's26': r'Giới hạn hữu hạn buộc các số hạng bậc thấp ở tử triệt tiêu; với hiệu hai căn thì nhân lượng liên hợp.',
    'h26': r'Trong khai triển Maclaurin của tử, mọi hệ số có bậc thấp hơn bậc của mẫu phải bằng 0; hệ số cùng bậc với mẫu cho giá trị $L$.',
    'n26a': r'Tiệm cận xiên: $a = \lim\dfrac{f(x)}{x}$, $b = \lim\left(f(x) - ax\right)$; với phân thức, chia đa thức là nhanh nhất.',
    'n26c': r'Mẫu tiến về 0 mà giới hạn hữu hạn thì tử cũng phải tiến về 0: điều kiện này cho $a$.',
    'n26d': r'Mẫu có nghiệm kép nên tử cũng phải có nghiệm kép tại đó: $g(x_0) = g\'(x_0) = 0$.',
    's27': r'Có đạo hàm tại điểm nối cần hai điều kiện: liên tục, và đạo hàm trái bằng đạo hàm phải.',
    'h27': r'Có đạo hàm cấp hai tại điểm nối: giá trị, đạo hàm cấp một và đạo hàm cấp hai ở hai phía đều phải khớp nhau.',
    # ----- đạo hàm, tích phân một biến -----
    's10': r'Chọn đúng công cụ: Leibniz cho đạo hàm cấp cao của tích; đạo hàm hai vế cho hàm ẩn; lấy lôgarit cho $u^v$; $\dfrac{dy}{dx} = \dfrac{y\'_t}{x\'_t}$ cho đường cong tham số.',
    'h10': r'Hệ số của $x^n$ trong tích hai khai triển là tổng các tích hệ số có tổng bậc bằng $n$; hệ số Maclaurin bậc $n$ bằng $\dfrac{f^{(n)}(0)}{n!}$.',
    's28': r'Công = $\displaystyle\int$ (trọng lượng một lớp nước) $\times$ (quãng đường nâng lớp đó); các lớp ở độ sâu khác nhau đi quãng đường khác nhau.',
    'h28': r'Tích phân suy rộng: tính $\displaystyle\int_a^b$ rồi cho $b \to +\infty$; độ dài cung: $L = \displaystyle\int\sqrt{1 + y\'^2}\,dx$.',
    # ----- hàm nhiều biến -----
    's11': r'Đạo hàm riêng theo một biến thì coi biến kia là hằng số; với hàm ẩn $F(x,y,z) = 0$: $z\'_x = -\dfrac{F\'_x}{F\'_z}$.',
    'h11': r'Phải chia cho độ dài $|\vec l|$: đạo hàm theo hướng dùng véc tơ đơn vị.',
    'n11e': r'Tính $f\'_x$ trước rồi đạo hàm tiếp theo $y$; với hàm đa thức, $f\'\'_{xy} = f\'\'_{yx}$.',
    'n11b': r'$\Delta f$ chỉ gồm $f\'\'_{xx}$ và $f\'\'_{yy}$, không có đạo hàm hỗn hợp.',
    'n11a': r'Tính $u, v$ tại điểm đã cho trước rồi mới thay vào các đạo hàm riêng; phải cộng đủ hai nhánh qua $u$ và qua $v$.',
    'n11c': r'Tốc độ tăng lớn nhất là độ dài của gradient, không phải tổng hai đạo hàm riêng.',
    'n11d': r'Mặt phẳng tiếp xúc dùng giá trị các đạo hàm riêng tại tiếp điểm; cho $x = y = 0$ để tìm giao điểm với trục $Oz$.',
    's12': r'$df = f\'_xdx + f\'_ydy$; khi tính gần đúng, $\Delta x$ và $\Delta y$ có thể mang dấu âm.',
    'h12': r'Lấy lôgarit rồi vi phân: sai số tương đối của tích, thương bằng tổng các sai số tương đối nhân với trị tuyệt đối của số mũ.',
    's13': r'Giải đủ hệ $f\'_x = f\'_y = 0$ (đừng bỏ sót nghiệm), rồi xét dấu $AC - B^2$ tại từng điểm dừng.',
    'h13': r'Rút một biến từ điều kiện, hoặc dùng $\nabla f = \lambda\nabla g$; nhớ kiểm tra đó là giá trị lớn nhất hay nhỏ nhất.',
    's47': r'Hàm bậc hai: nhóm thành tổng các bình phương; hàm khác: tìm điểm dừng rồi xét dấu $AC - B^2$.',
    'h47': r'Tại cực trị có điều kiện $\nabla f$ cùng phương với $\nabla g$; với hàm bậc nhất trên mặt cầu có thể dùng bất đẳng thức Cauchy – Schwarz.',
    'g2': r'Điểm dừng: $f\'_x = f\'_y = 0$; phân loại bằng dấu của $AC - B^2$ và của $A$.',
    'hg2': r'Giá trị lớn nhất, nhỏ nhất trên miền đóng: so sánh giá trị tại điểm dừng bên trong với giá trị trên biên.',
    'ngB': r'$AC - B^2 > 0$ và $A > 0$ tại mọi điểm nên điểm dừng duy nhất là điểm cực tiểu.',
    'ngC': r'Không phải điểm dừng nào cũng là cực trị: $AC - B^2 < 0$ là điểm yên ngựa.',
    'ngD': r'Gradient, đạo hàm theo hướng và mặt phẳng tiếp xúc đều dùng chung hai giá trị $f\'_x(M)$, $f\'_y(M)$.',
    # ----- chuỗi -----
    's14': r'So sánh với $\sum\dfrac{1}{n^\alpha}$ (hội tụ khi $\alpha > 1$); có $n!$ hoặc $a^n$ thì dùng D’Alembert; có lũy thừa bậc $n$ thì dùng Cauchy.',
    'n14d': r'So sánh với $\sum\dfrac{1}{n^\alpha}$ (hội tụ khi $\alpha > 1$); có $n!$ hoặc $a^n$ thì dùng D’Alembert; có lũy thừa bậc $n$ thì dùng Cauchy.',
    'n14e': r'Trường hợp biên $p = 1$ phân kỳ: $\sum\dfrac{1}{n\ln n}$ phân kỳ dù số hạng nhỏ hơn $\dfrac1n$.',
    'n14a': r'Chỉ so bậc của tử và mẫu: cần (bậc mẫu $-$ bậc tử) $> 1$; bằng đúng 1 thì vẫn phân kỳ.',
    'n14b': r'Khi tỉ số D’Alembert bằng đúng 1 thì tiêu chuẩn không kết luận được: phải xét riêng giá trị biên của $c$.',
    'n14c': r'Tiêu chuẩn Cauchy: lấy căn bậc $n$ làm mất số mũ $n$; số mũ $2n$ thì còn lại bình phương.',
    's15': r'Leibniz: $a_n$ giảm về 0 thì chuỗi đan dấu hội tụ; hội tụ tuyệt đối phải xét thêm $\sum a_n$; nếu $a_n \not\to 0$ thì chuỗi phân kỳ.',
    's30': r'Tổng dạng sai phân: viết vài số hạng đầu để thấy những số hạng nào còn lại sau khi triệt tiêu.',
    'n30c': r'$S_N$ là tổng hữu hạn, chưa lấy giới hạn: đừng nhầm với tổng của cả chuỗi.',
    'n30d': r'Tách thành hai chuỗi quen thuộc rồi thay $x = \dfrac1q$.',
    'n30a': r'Tách $n = (n + 1) - 1$ để được hiệu của hai số hạng liên tiếp.',
    'n30b': r'Lôgarit của tích thành tổng: tách $\ln\dfrac{(n-1)(n+1)}{n^2}$ thành hiệu để các số hạng triệt tiêu.',
    's31': r'Chuỗi hình học: $\displaystyle\sum_{n\ge n_0}q^n = \dfrac{q^{n_0}}{1 - q}$ với $|q| < 1$; chú ý chỉ số bắt đầu.',
    'c32': r'Đạo hàm hoặc tích phân từng số hạng của $\displaystyle\sum x^n = \dfrac{1}{1 - x}$ để có các chuỗi liên quan; chỉ đúng khi $|x| < 1$.',
    'h32': r'Nhận ra chuỗi quen thuộc ($e^x$, $\ln(1 + x)$, $\arctan x$, ...) rồi thay giá trị $x$ thích hợp.',
    's48': r'$R = \lim\left|\dfrac{a_n}{a_{n+1}}\right|$; tại hai đầu mút của khoảng hội tụ phải xét riêng.',
    'n48d': r'Chuỗi theo $x^k$: đặt $t = x^k$; bán kính theo $x$ là căn bậc $k$ của bán kính theo $t$.',
    'n48b': r'Bên trong khoảng hội tụ chuỗi luôn hội tụ; hai đầu mút phải xét riêng (một đầu là chuỗi điều hòa, đầu kia là chuỗi đan dấu).',
    'n48c': r'Giải bất phương trình theo $x$: độ dài miền hội tụ bằng $2R$ chia cho hệ số của $x$ trong ngoặc.',
    # ----- phương trình vi phân -----
    's16': r'Nhận dạng: tách biến $y\' = f(x)g(y)$; tuyến tính $y\' + p(x)y = q(x)$; Bernoulli có thêm $y^\alpha$ ở vế phải; đẳng cấp $y\' = \varphi\left(\dfrac{y}{x}\right)$.',
    's17': r'Đưa về dạng chuẩn rồi mới tìm thừa số tích phân $e^{\int p\,dx}$ (hoặc kiểm tra $P\'_y = Q\'_x$); hằng số $C$ xác định từ điều kiện đầu.',
    'h17': r'Bernoulli: đặt $z = y^{1-\alpha}$; với $\alpha = 2$ là $z = \dfrac1y$, khi đó $z\' = -\dfrac{y\'}{y^2}$.',
    'n17c': r'Sau khi nhân thừa số tích phân, vế trái phải là đạo hàm của một tích: $(y\sin x)\'$.',
    'n17a': r'Phương trình đẳng cấp: đặt $y = ux$ thì $y\' = u\'x + u$; giải xong nhớ đổi lại $u = \dfrac{y}{x}$.',
    'n17b': r'Kiểm tra $P\'_y = Q\'_x$ trước; nghiệm tổng quát là $u(x,y) = C$ với $u\'_x = P$, $u\'_y = Q$.',
    'n17e': r'Với $y\' = f(ax + by + c)$, đặt $u = ax + by + c$ sẽ được phương trình tách biến.',
    's18': r'Phương trình $y\' = k(M - y)$ có nghiệm $y = M + (y_0 - M)e^{-kt}$; với $k = \dfrac{\ln 2}{T}$ thì $e^{-kT} = \dfrac12$.',
    'h18': r'Thay $t = 0$ để tìm hằng số trong công thức nghiệm; với $k = \dfrac{\ln 2}{T}$ thì $e^{-kT} = \dfrac12$.',
    'c33': r'Tách biến: đưa $y$ về một vế, $x$ về một vế rồi lấy tích phân; hằng số $C$ chỉ cần viết ở một vế.',
    'h33': r'Tìm nghiệm tổng quát trước, rồi dùng điều kiện đầu để xác định $C$ (và dấu của căn nếu có).',
    'c34': r'Tuyến tính: nhân thừa số tích phân $e^{\int p\,dx}$; đẳng cấp: đặt $y = ux$.',
    'h34': r'Đưa về dạng $y\' + p(x)y = q(x)$ rồi nhân thừa số tích phân $e^{\int p\,dx}$; $C$ xác định từ điều kiện đầu.',
    's35': r'Lượng muối: $y\' =$ (tốc độ vào) $-$ (tốc độ ra), với tốc độ ra = nồng độ hiện tại $\times$ lưu lượng; chú ý thể tích trong bể có thay đổi hay không.',
    's19': r'Hai nghiệm thực phân biệt: $C_1e^{k_1x} + C_2e^{k_2x}$; nghiệm kép: $(C_1 + C_2x)e^{kx}$; nghiệm phức $\alpha \pm i\beta$: $e^{\alpha x}(C_1\cos\beta x + C_2\sin\beta x)$.',
    'h19': r'Cộng hưởng: khi số mũ (hoặc tần số) của vế phải trùng nghiệm đặc trưng, nghiệm riêng phải nhân thêm $x$ (nghiệm kép: $x^2$).',
    'n19a': r'Đi ngược: từ nghiệm suy ra nghiệm đặc trưng, rồi $k^2 - (k_1 + k_2)k + k_1k_2 = 0$; chú ý dấu của hệ số $y\'$.',
    'n19c': r'Nghiệm riêng cho vế phải bậc nhất phải lấy đủ $Ax + B$, kể cả khi vế phải không có hằng số.',
    'n19d': r'Trước khi chọn dạng $Ae^{cx}$, kiểm tra $c$ có trùng nghiệm đặc trưng không.',
    'n19b': r'Bội của số mũ (hoặc của $\alpha \pm i\beta$) trong phương trình đặc trưng quyết định nhân thêm $1$, $x$ hay $x^2$.',
    's49': r'Tìm nghiệm tổng quát, dùng hai điều kiện đầu để tìm $C_1, C_2$, rồi mới thay số.',
    'h49': r'Nghiệm = nghiệm thuần nhất + nghiệm riêng; điều kiện đầu áp cho nghiệm đầy đủ, không phải cho riêng phần thuần nhất.',
    'n49c': r'Nghiệm bị chặn khi $x \to +\infty$ nên hệ số của số hạng có mũ dương phải bằng 0.',
    'n49a': r'Không cần tìm $y$: lấy tích phân trực tiếp hai vế của phương trình.',
    'n49b': r'Nghiệm = nghiệm thuần nhất + nghiệm riêng; điều kiện đầu áp cho nghiệm đầy đủ.',
    # ----- tích phân bội -----
    's20': r'Vẽ miền $D$ trước khi đổi thứ tự; cận của tích phân ngoài phải là hằng số.',
    'h20': r'Sau khi đổi thứ tự, tích phân trong tạo ra đúng thừa số cần thiết để tích phân còn lại tính được bằng đổi biến.',
    'n20a': r'Tích phân trong lấy theo $y$ với cận phụ thuộc $x$; kết quả là hàm của $x$ rồi mới lấy tích phân ngoài.',
    'n20d': r'Tích phân trong lấy theo $y$ với cận phụ thuộc $x$; kết quả là hàm của $x$ rồi mới lấy tích phân ngoài.',
    'n20b': r'Diện tích = $\displaystyle\int$ (đường trên $-$ đường dưới)$\,dx$; cận là hoành độ các giao điểm.',
    'n20c': r'Cận của $r$ là căn bậc hai của các số ở hai vế; không quên định thức Jacobi $r$.',
    's21': r'Tọa độ trụ: $dV = r\,dr\,d\varphi\,dz$; tọa độ cầu: $dV = \rho^2\sin\theta\,d\rho\,d\theta\,d\varphi$; cận của $z$ đi từ mặt dưới lên mặt trên.',
    'h21': r'Góc $\theta$ tính từ trục $Oz$: mặt nón $z = c\sqrt{x^2 + y^2}$ ứng với $\tan\theta = \dfrac1c$.',
    's36': r'Trong tọa độ cực $dxdy = r\,dr\,d\varphi$; đường tròn $x^2 + y^2 = 2ax$ là $r = 2a\cos\varphi$ với $-\dfrac{\pi}{2} \le \varphi \le \dfrac{\pi}{2}$.',
    'h36': r'Cận của $r$ phụ thuộc $\varphi$ nên phải lấy tích phân theo $r$ trước, rồi mới theo $\varphi$.',
    'n36a': r'Đổi sang tọa độ cực để có thừa số $r$; khi đó $re^{\pm r^2}$ tính được nguyên hàm.',
    'n36b': r'Miền $D$ là hình chiếu của vật thể: nơi mặt cong cắt mặt phẳng $z = 0$.',
    'n36c': r'Điều kiện về $x, y$ quy định cận của góc $\varphi$; nên vẽ hình để tránh nhầm góc.',
    's37': r'Tọa độ trụ hợp với paraboloid, mặt nón; tọa độ cầu hợp với hình cầu; không quên định thức Jacobi.',
    'h37': r'Trong tọa độ cầu $\sqrt{x^2 + y^2 + z^2} = \rho$ và $dV = \rho^2\sin\theta\,d\rho\,d\theta\,d\varphi$.',
    's50': r'$V = \displaystyle\iint_D z\,dxdy$ với $D$ là hình chiếu của vật thể lên $Oxy$: xác định $D$ trước.',
    'h50': r'Elipxoit: đổi biến $x = au,\ y = bv,\ z = cw$ đưa về hình cầu đơn vị, định thức Jacobi bằng $abc$.',
    # ----- tích phân đường -----
    's38': r'Tích phân đường loại một: $ds = \sqrt{x\'^2 + y\'^2}\,dt$, không phụ thuộc chiều đi trên đường cong.',
    's39': r'Tích phân đường loại hai: thay $y = y(x)$, $dy = y\'dx$; với đường cong kín thì dùng công thức Green.',
    'h39': r'Green: $\displaystyle\oint_C P\,dx + Q\,dy = \iint_D\left(Q\'_x - P\'_y\right)dxdy$, với chiều dương là ngược chiều kim đồng hồ.',
    'n39b': r'Trên đoạn thẳng, $ds = |AB|\,dt$ với $0 \le t \le 1$; kết quả không phụ thuộc chiều đi.',
    'n39a': r'Khi tích phân không phụ thuộc đường đi, chỉ cần tìm hàm thế $u$: kết quả là $u(B) - u(A)$.',
    'n39c': r'Điều kiện không phụ thuộc đường đi là hai đạo hàm chéo bằng nhau: $P\'_y = Q\'_x$.',
    'n39d': r'Công thức Green đổi tích phân trên biên thành tích phân hai lớp trên miền; chú ý thứ tự $Q\'_x - P\'_y$.',
}
